using CreatorPay.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace CreatorPay.Infrastructure.Persistence.Configurations;

internal sealed class OfflineSyncBatchConfiguration : IEntityTypeConfiguration<OfflineSyncBatch> { public void Configure(EntityTypeBuilder<OfflineSyncBatch> b) { b.ConfigureEntity(); b.Property(x => x.PublicBatchId).HasMaxLength(100); b.Property(x => x.AppVersion).HasMaxLength(40); b.Property(x => x.DeviceReferenceHash).HasMaxLength(64); b.Property(x => x.CorrelationId).HasMaxLength(100); b.HasIndex(x => x.PublicBatchId).IsUnique(); b.HasIndex(x => x.ReceivedAtUtc); } }
internal sealed class OfflineSyncItemResultConfiguration : IEntityTypeConfiguration<OfflineSyncItemResult> { public void Configure(EntityTypeBuilder<OfflineSyncItemResult> b) { b.ConfigureEntity(); b.Property(x => x.ClientOperationId).HasMaxLength(100); b.Property(x => x.IdempotencyKey).HasMaxLength(200); b.Property(x => x.RequestHash).HasMaxLength(64); b.Property(x => x.ResultStatus).HasMaxLength(30); b.Property(x => x.ErrorCode).HasMaxLength(80); b.Property(x => x.SafeMessage).HasMaxLength(300); b.Property(x => x.CorrelationId).HasMaxLength(100); b.HasIndex(x => new { x.CashierUserId, x.ClientOperationId }).IsUnique(); b.HasIndex(x => x.ResultStatus); b.HasOne(x => x.Batch).WithMany(x => x.Items).HasForeignKey(x => x.OfflineSyncBatchId).OnDelete(DeleteBehavior.Restrict); } }
